const compressed = ``;

let cache;
async function loadFiles(){
 if(!cache)cache=(async()=>{const bytes=Uint8Array.from(atob(compressed.replace(/\s+/g,'')),c=>c.charCodeAt(0));const content=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return new Response(content).json();})();
 return cache;
}
// Cache (ADR 0022): código e páginas sempre revalidam (no-cache + ETag → 304 sem corpo);
// binários em /assets/ ficam 1 dia no navegador. Nenhuma resposta é privada: o Worker só serve arquivos públicos.
const bytesCache=new Map(),etagCache=new Map();
function cacheControlFor(path,type){return path.startsWith('/assets/')&&!type.startsWith('text/')?'public, max-age=86400':'no-cache';}
async function etagFor(path,payload){
 if(etagCache.has(path))return etagCache.get(path);
 const subtle=globalThis.crypto?.subtle;if(!subtle)return null;
 const digest=new Uint8Array(await subtle.digest('SHA-256',payload));
 const tag='"'+Array.from(digest.slice(0,16),b=>b.toString(16).padStart(2,'0')).join('')+'"';
 etagCache.set(path,tag);return tag;
}
export default {async fetch(request){
 try {
  const url=new URL(request.url);
  if(!['GET','HEAD'].includes(request.method))return new Response('Method Not Allowed',{status:405});
  let path=decodeURIComponent(url.pathname);
  if(path==='/')path='/index.html';
  if(path.includes('..')||path.includes('\\'))return new Response('Bad Request',{status:400});
  const asset=(await loadFiles())[path];
  if(!asset)return new Response('Not Found',{status:404});
  let payload=bytesCache.get(path);
  if(!payload){payload=Uint8Array.from(atob(asset.b),c=>c.charCodeAt(0));bytesCache.set(path,payload);}
  const headers={'content-type':asset.t+((asset.t.startsWith('text/')||asset.t.includes('javascript')||asset.t.includes('json'))?'; charset=utf-8':''),'cache-control':cacheControlFor(path,asset.t),'x-content-type-options':'nosniff','referrer-policy':'no-referrer','x-frame-options':'DENY','content-security-policy':"default-src 'self'; script-src 'self' 'sha256-twQ8uMXpM7NaLrpR+qMcLE+cjXht2CG3SN/9WwmhFRQ=' https://cdn.jsdelivr.net https://unpkg.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; img-src 'self' data: blob: https:; connect-src 'self' https://gkjqfirlcmmlhuokszlz.supabase.co wss://gkjqfirlcmmlhuokszlz.supabase.co; worker-src 'self'; manifest-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'",'permissions-policy':'geolocation=(), microphone=()','strict-transport-security':'max-age=31536000'};
  if(path==='/auditoria-imagens.html'||path==='/auditoria-imagens.js')headers['x-robots-tag']='noindex, nofollow';
  const etag=await etagFor(path,payload);
  if(etag){headers.etag=etag;const match=(request.headers.get('if-none-match')||'').split(',').map(v=>v.trim().replace(/^W\//,''));if(match.includes(etag))return new Response(null,{status:304,headers});}
  return new Response(request.method==='HEAD'?null:payload,{status:200,headers});
 } catch(e){return new Response('Internal server error',{status:500});}
}};